# For 9x2, try output as 9x2 grid
# Mark both columns as 2 if they BOTH have non-zero values
def transform_9x2(test):
    result = []
    for row in test:
        left, right = row[0], row[1]
        if left != 0 and right != 0:
            result.append([2, 2])
        else:
            result.append([0, 0])
    return result

print(f"9x2 both-active: {transform_9x2(test)}")

# Or keep original non-zero values
def transform_9x2_preserve(test):
    result = []
    for row in test:
        if row[0] != 0 and row[1] != 0:
            result.append([row[0], row[1]])
        else:
            result.append([0, 0])
    return result

print(f"9x2 preserve: {transform_9x2_preserve(test)}")

# Or mark with 2 instead of preserving value
def transform_9x2_mark2(test):
    result = []
    for row in test:
        if row[0] != 0 and row[1] != 0:
            result.append([2, 2])  # or [row[0], row[1]]
        else:
            result.append([0, 0])
    return result

print(f"9x2 mark2: {transform_9x2_mark2(test)}")
